251	fn complete_option(
252	    arg: &clap_lex::ParsedArg<'_>,
253	    cmd: &clap::Command,
254	    current_dir: Option<&std::path::Path>,
255	) -> Vec<CompletionCandidate> {
256	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
257	    let mut completions = Vec::<CompletionCandidate>::new();
258	    if arg.is_empty() {
259	        completions.extend(longs_and_visible_aliases(cmd));
260	        completions.extend(hidden_longs_aliases(cmd));
261	
262	        let dash_or_arg = if arg.is_empty() {
263	            "-".into()
264	        } else {
265	            arg.to_value_os().to_string_lossy()
266	        };
267	        completions.extend(
268	            shorts_and_visible_aliases(cmd)
269	                .into_iter()
270	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
271	        );
272	    } else if arg.is_stdio() {
273	        // HACK: Assuming knowledge of is_stdio
274	        let dash_or_arg = if arg.is_empty() {
275	            "-".into()
276	        } else {
277	            arg.to_value_os().to_string_lossy()
278	        };
279	        completions.extend(
280	            shorts_and_visible_aliases(cmd)
281	                .into_iter()
282	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
283	        );
284	
285	        completions.extend(longs_and_visible_aliases(cmd));
286	        completions.extend(hidden_longs_aliases(cmd));
287	    } else if arg.is_escape() {
288	        // HACK: Assuming knowledge of is_escape
289	        completions.extend(longs_and_visible_aliases(cmd));
290	        completions.extend(hidden_longs_aliases(cmd));
291	    } else if let Some((flag, value)) = arg.to_long() {
292	        if let Ok(flag) = flag {
293	            if let Some(value) = value {
294	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
295	                    completions.extend(
296	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
297	                            .into_iter()
298	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
299	                    );
300	                }
301	            } else {
302	                completions.extend(
303	                    longs_and_visible_aliases(cmd)
304	                        .into_iter()
305	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
306	                );
307	                completions.extend(
308	                    hidden_longs_aliases(cmd)
309	                        .into_iter()
310	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
311	                );
312	            }
313	        }
314	    } else if let Some(short) = arg.to_short() {
315	        if !short.is_negative_number() {
316	            // Find the first takes_values option.
317	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
318	
319	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
320	            if let Some(opt) = takes_value_opt {
321	                let mut peek_short = short.clone();
322	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
323	                    short.next_flag();
324	                    true
325	                } else {
326	                    false
327	                };
328	
329	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
330	                completions.extend(
331	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
332	                        .into_iter()
333	                        .map(|comp| {
334	                            let sep = if has_equal { "=" } else { "" };
335	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
336	                        }),
337	                );
338	            } else {
339	                completions.extend(
340	                    shorts_and_visible_aliases(cmd)
341	                        .into_iter()
342	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
343	                );
344	            }
345	        }
346	    }
347	    debug!("complete_option: completions={completions:?}");
348	    completions
349	}
