461	fn complete_candidates_str(
462	    value: &str,
463	    mut values: Vec<CompletionCandidate>,
464	) -> Vec<CompletionCandidate> {
465	    debug!("complete_candidates_str: value={value:?}");
466	
467	    values.retain(|comp| comp.get_value().starts_with(value));
468	    values
469	}
