506	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
507	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
508	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
509	    debug!("longs: name={}", p.get_name());
510	
511	    p.get_arguments()
512	        .filter_map(|a| {
513	            a.get_long_and_visible_aliases().map(|longs| {
514	                longs
515	                    .into_iter()
516	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
517	            })
518	        })
519	        .flatten()
520	        .collect()
521	}
522	
523	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
524	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
525	    debug!("longs: name={}", p.get_name());
526	
527	    p.get_arguments()
528	        .filter_map(|a| {
529	            a.get_aliases().map(|longs| {
530	                longs.into_iter().map(|s| {
531	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
532	                })
533	            })
534	        })
535	        .flatten()
536	        .collect()
537	}
